import {SPRITE_FRAMES} from './sprite-frames.js?v=1.7.11';
export function portrait(character,large=false){if(character.sprite){const sheet=SPRITE_FRAMES[`${character.sprite}-actions`],[x,y,w,h]=sheet.frames[0][0],side=Math.max(w,h)*1.12,left=x+w/2-side/2,top=y+h/2-side/2;return `<svg class="portrait portrait-sprite ${large?'portrait-large':''}" role="img" aria-label="${character.name} 도트 일러스트" viewBox="${left} ${top} ${side} ${side}"><defs><clipPath id="portrait-clip-${character.id}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><image clip-path="url(#portrait-clip-${character.id})" href="./sprites/${character.sprite}-actions.png" width="${sheet.size[0]}" height="${sheet.size[1]}" /></svg>`;}const c=character.color,f=character.sex==='female';return `<svg class="portrait ${large?'portrait-large':''}" viewBox="0 0 320 380" role="img" aria-label="${character.name} 캐릭터 일러스트"><defs><linearGradient id="coat-${character.id}" x1="0" x2="1"><stop stop-color="#182b32"/><stop offset=".6" stop-color="#34454c"/><stop offset="1" stop-color="#131f26"/></linearGradient><radialGradient id="aura-${character.id}"><stop stop-color="${c}" stop-opacity=".26"/><stop offset="1" stop-color="${c}" stop-opacity="0"/></radialGradient></defs><circle cx="170" cy="180" r="155" fill="url(#aura-${character.id})"/><g stroke="${c}" fill="none" opacity=".25"><circle cx="160" cy="170" r="108"/><path d="M25 170h270M160 35v270"/><circle cx="160" cy="170" r="118" stroke-dasharray="2 18"/></g><path d="M116 290 96 380h55l17-94 14 94h52l-24-110" fill="#131d23"/><path d="m119 152-36 28-29 132 31 7 32-93-22 134 67-17 61 18-19-136 28 85 27-13-38-117-39-29" fill="url(#coat-${character.id})" stroke="#51666b" stroke-width="1"/><path d="m131 148 29 26 30-27 4 120-35 39-38-41z" fill="#0d161c"/><path d="m130 156 30 27-29 32-11-48m70-10-30 26 30 36 12-47" fill="#4b6062"/><path d="m160 184-2 126" stroke="${c}" stroke-width="2"/><path d="M141 134v21l19 18 21-21-3-23" fill="#acaaa0"/><path d="M133 83q29-22 53 2l-2 41-12 17h-23l-16-20z" fill="#c8c6b7"/><path d="m130 116-5-30 11-21 24-9 29 11 10 22-9 32-7-27-15-13-24 21-10-6z" fill="#101b22"/><path d="m143 115 10-1m15 0 9-2" stroke="${c}" stroke-width="3"/><path d="m155 132 14-1" stroke="#666b66" stroke-width="2"/>${f?'<path d="m127 86-9 72 17 30 6-43-7-37m52-27 17 83-21-11-1-34" fill="#101b22"/>':''}<path d="m84 306-4 23-17 8-11-13 3-17m180-7 4 19 17 8 11-15-8-20" fill="#a8ada4"/><g fill="none" stroke="${c}"><path d="m74 245 8-33 11-17m116 12 10 29" stroke-width="3"/><circle cx="251" cy="310" r="29" opacity=".6"/><circle cx="251" cy="310" r="36" stroke-dasharray="3 9"/><path d="m235 313 14-27-2 20 15-8-13 29 1-20z" fill="${c}" stroke="none"/></g><g fill="${c}"><rect x="104" y="202" width="4" height="15"/><rect x="202" y="192" width="4" height="15"/></g></svg>`;}
export function cityArt(){return `<svg class="city-art" viewBox="0 0 800 620" preserveAspectRatio="xMidYMid slice" role="img" aria-label="거대한 균열과 네온 불빛이 비치는 밤의 도심"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#172a30"/><stop offset=".65" stop-color="#385451"/><stop offset="1" stop-color="#0e2021"/></linearGradient><radialGradient id="rift"><stop stop-color="#d9f9ac" stop-opacity=".7"/><stop offset=".3" stop-color="#b0ef8a" stop-opacity=".25"/><stop offset="1" stop-color="#94e7ac" stop-opacity="0"/></radialGradient><linearGradient id="road" x2="0" y2="1"><stop stop-color="#3f6660"/><stop offset="1" stop-color="#101d20"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="6"/></filter><pattern id="windows" width="23" height="28" patternUnits="userSpaceOnUse"><rect x="6" y="6" width="5" height="11" fill="#a6d1ad" opacity=".15"/></pattern></defs><rect width="800" height="620" fill="url(#sky)"/><circle cx="433" cy="212" r="225" fill="url(#rift)"/><g fill="#203438"><path d="M230 370V190h45v-28h30v208M297 370V235h65v135M514 370V157h34v-26h19v239M573 370V200h51v170"/></g><g fill="#14262b" stroke="#45645f" stroke-opacity=".2"><path d="M0 0h161v402H0zM159 90h74v314h-74zM630 39h170v408H630zM569 145h64v260h-64z"/><path d="M0 37h148v367H0zM642 64h158v343H642z" fill="url(#windows)"/></g><path d="M0 620 300 367h241l259 253" fill="url(#road)"/><path d="m0 512 294-146M800 515 540 366" stroke="#6c9881" stroke-width="2" opacity=".5"/><path d="m402 384-18 236m63-236 24 236" stroke="#b2c49a" stroke-width="2" opacity=".28" stroke-dasharray="32 33"/><path d="m34 577 291-170m455 170-266-170" stroke="#87bb9c" opacity=".16" stroke-width="8"/><ellipse cx="436" cy="255" rx="64" ry="153" fill="#a5ef8d" opacity=".25" filter="url(#glow)"/><path d="m462 83-45 88 26 43-40 70 20 40-28 55 48-67-10-31 34-76-24-38z" fill="#c7f5b0"/><path d="m450 119-47 62 21 37-38 74m56-42 28-17 12-43m-61 116-36 18-15 37" fill="none" stroke="#b7f9b4" stroke-width="2"/><g fill="#17282a"><path d="M39 431v-195h8v195m0-195h70v9H47M707 436V265h7v171m-69-171h62v8h-62"/></g><path d="M48 247h67m533 29h54" stroke="#d5e2b4" stroke-width="4"/><g><rect x="172" y="210" width="29" height="101" rx="2" fill="#1e4d49"/><text x="187" y="237" fill="#9ccabd" font-size="15" text-anchor="middle" font-family="sans-serif">심<tspan x="187" dy="24">야</tspan><tspan x="187" dy="24">약</tspan></text><rect x="657" y="328" width="85" height="22" fill="#4d6653" opacity=".6"/><text x="698" y="344" font-size="12" fill="#d4e1b6" text-anchor="middle" font-family="sans-serif" letter-spacing="3">24 OPEN</text></g><g fill="#102024" stroke="#4d6760"><path d="m151 436 12-24h62l18 24v29h-92z"/><path d="m590 421 8-19h47l14 19v25h-69z"/></g><g fill="#d1b987"><rect x="157" y="440" width="17" height="4"/><rect x="219" y="440" width="17" height="4"/></g><g stroke="#aedfcb" opacity=".17">${Array.from({length:42},(_,i)=>{let x=(i*137)%800,y=(i*83)%600;return `<path d="m${x} ${y} -9 25"/>`;}).join('')}</g><g fill="#ceefb2" opacity=".8">${Array.from({length:18},(_,i)=>`<circle cx="${300+(i*47)%260}" cy="${80+(i*79)%390}" r="${1+i%2}"/>`).join('')}</g></svg>`;}
export function icon(name){const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',flask:'M9 3h6M10 3v7L4 20h16l-6-10V3M8 15h8',book:'M4 4h6l2 2 2-2h6v16h-6l-2 1-2-1H4zM12 6v15',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M5 21v-3a7 7 0 0 1 14 0v3',quest:'M6 4h12v17H6zM9 4V2h6v2M9 10h6M9 14h6',arrow:'M4 12h16M14 6l6 6-6 6',bolt:'M13 2 4 14h7l-1 8 10-13h-7z',sound:'M11 4 5 9H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 4a11 11 0 0 1 0 16',mute:'M11 4 5 9H2v6h3l6 5zM16 9l6 6m0-6-6 6',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01',close:'M6 6l12 12M6 18 18 6',pause:'M8 4v16M16 4v16',play:'m8 4 12 8-12 8z',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 10v4m-2-2h4',diamond:'m12 2 9 10-9 10-9-10z',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 7M4 12l2 7a8 8 0 0 0 13-2'};return `<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.bolt}"/></svg>`;}
